  "fixed_code": "@Composable
fun PlaybackCard(
	modifier: Modifier,
	media: MediaCallback,
	packageInfo: ResolveInfo,
) {
	val context = LocalContext.current
	val packageManager = context.packageManager

	val song =
		media.playingSong ?: run {
			EmptyPlayerCard(
				modifier = modifier,
				packageInfo = packageInfo,
			)
			return
		}

	val generatedBitmap: Bitmap? =
		remember(song.coverFilePath) {
			StorageHelper.loadBitmapFromFile(song.coverFilePath)
		}

	val coverPalette = generatedBitmap?.let { Palette.from(it).generate() }
	val dominantColor =
		Color(coverPalette?.getVibrantColor(Color.White.toArgb()) ?: Color.Black.toArgb())

	val playbackCornerRadius by animateDpAsState(
		targetValue = if (media.isPlaying) 16.dp else 96.dp,
		label = "Playback corner radius",
	)

	val applicationInfo = packageInfo.activityInfo.applicationInfo
	val appIcon = remember(applicationInfo) { packageManager.getApplicationIcon(applicationInfo) }

	val containerColor =
		Color(
			ColorUtils.blendARGB(
				dominantColor.toArgb(),
				Color.White.toArgb(),
				0.6f,
			),
		)

	Card(
		modifier =
			modifier
				.height(IntrinsicSize.Min)
				.fillMaxWidth()
				.clip(MaterialTheme.shapes.extraLarge),
		shape = MaterialTheme.shapes.extraLarge,
	) {
		Box(
			modifier =
				Modifier
					.fillMaxSize(),
		) {
			AsyncImage(
				model = appIcon,
				contentDescription = null,
				imageLoader = context.imageLoader,
				modifier =
					Modifier
						.padding(16.dp)
						.align(Alignment.TopStart)
						.size(32.dp)
						.zIndex(1f),
			)
			Crossfade(
				modifier = Modifier.fillMaxSize(),
				targetState = generatedBitmap,
				label = "Cover image",
			) { cover ->
				AsyncImage(
					model = cover,
					contentDescription = null,
					imageLoader = context.imageLoader,
					contentScale = ContentScale.Crop,
					colorFilter =
						ColorFilter.tint(
							color = dominantColor.copy(alpha = 0.5f),
							blendMode = BlendMode.Color,
						),
					modifier =
						Modifier
							.fillMaxSize()
							.drawWithContent {
								drawContent()
								drawRect(
									brush =
										Brush.radialGradient(
											listOf(
												Color.Transparent,
												Color.Black.copy(alpha = 0.35f),
											),
											center = size.center,
											radius = size.width / 2f,
										),
									size = size,
									blendMode = BlendMode.Darken,
								)
							},
				)
			}

			Column(
				modifier = Modifier.fillMaxSize(),
			) {
				Spacer(modifier = Modifier.weight(1f))

				Row(
					modifier = Modifier.fillMaxWidth(),
					verticalAlignment = Alignment.Bottom,
				) {
					Column(
						modifier =
							Modifier
								.weight(1f)
								.padding(
									start = 24.dp,
									end = 24.dp,
									bottom = 24.dp,
								),
						verticalArrangement = Arrangement.spacedBy(2.dp),
					) {
						AnimatedContent(
							targetState = song.title,
							label = "Song title",
							transitionSpec = {
								slideInHorizontally { height -> height } + fadeIn() togetherWith
									slideOutHorizontally { height -> -height } + fadeOut()
							},
						) { title ->
							Text(
								text = title,
								style = MaterialTheme.typography.titleLarge,
								fontWeight = FontWeight.Bold,
								color = Color.White,
								maxLines = 2,
								overflow = TextOverflow.Ellipsis,
							)
						}
						AnimatedContent(
							targetState = song.artist,
							label = "Song artist",
							transitionSpec = {
								slideInHorizontally { height -> height } + fadeIn() togetherWith
									slideOutHorizontally { height -> -height } + fadeOut()
							},
						) { artist ->
							Text(
								text = artist,
								style = MaterialTheme.typography.labelMedium,
								fontWeight = FontWeight.Bold,
								color = Color.White,
								maxLines = 1,
								overflow = TextOverflow.Ellipsis,
							)
						}
					}

					Row(
						modifier =
							Modifier
								.padding(end = 24.dp, bottom = 24.dp),
						horizontalArrangement = Arrangement.spacedBy(8.dp),
