        Surface(
            modifier, shape = RoundedCornerShape(8.dp),
            color = Color(0xFFF4511E)
        ) {}
        // 圆形的shape
        Surface(
            modifier = modifier,
            shape = CircleShape,
            color = Color(0xFF26C6DA)
        ) {}

        //切角矩形，也可以指定四个角不同的其角值，
        Surface(
            modifier = modifier,
            shape = CutCornerShape(10.dp),
            color = Color(0xFF7E57C2)
        ) {}
    }

    Text(
        text = "2、Surface可以通过border给内部控件设置边框，以及shadowElevation投影层深。",
