        Text(
            text = stringResource(R.string.setting_history_retention),
            style = MaterialTheme.typography.titleMedium,
        )
        Text(
            text = stringResource(R.string.setting_history_retention_desc),
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Spacer(modifier = Modifier.height(8.dp))

        var retentionExpanded by rememberSaveable { mutableStateOf(false) }
        val retentionOptions = listOf(
            "none" to stringResource(R.string.history_retention_none),
            "1month" to stringResource(R.string.history_retention_1month),
            "3months" to stringResource(R.string.history_retention_3months),
            "6months" to stringResource(R.string.history_retention_6months),
        )
        val currentRetentionLabel =
            retentionOptions.firstOrNull { it.first == historyRetention }?.second ?: historyRetention

        ExposedDropdownMenuBox(
            expanded = retentionExpanded,
            onExpandedChange = { retentionExpanded = it },
        ) {
            OutlinedTextField(
                value = currentRetentionLabel,
                onValueChange = {},
                readOnly = true,
                trailingIcon = { ExposedDropdownMenuDefaults.TrailingIcon(expanded = retentionExpanded) },
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics { testTagsAsResourceId = true }
                    .testTag("settings-history-retention")
                    .menuAnchor(MenuAnchorType.PrimaryNotEditable),
            )
            ExposedDropdownMenu(
                expanded = retentionExpanded,
                onDismissRequest = { retentionExpanded = false },
            ) {
                retentionOptions.forEach { (code, label) ->
                    DropdownMenuItem(
                        text = { Text(label) },
                        onClick = {
                            viewModel.setHistoryRetention(code)
                            retentionExpanded = false
                        },
                    )
                }
            }
        }

        HorizontalDivider(modifier = Modifier.padding(vertical = 16.dp))

        // Map theme — Auto / Light / Dark
        Text(
            text = stringResource(R.string.setting_map_theme),
            style = MaterialTheme.typography.titleMedium,
        )
        Text(
            text = stringResource(R.string.setting_map_theme_desc),
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Spacer(modifier = Modifier.height(8.dp))

        var themeExpanded by rememberSaveable { mutableStateOf(false) }
        val themeOptions = listOf(
            MapThemeMode.AUTO to stringResource(R.string.map_theme_auto),
            MapThemeMode.LIGHT to stringResource(R.string.map_theme_light),
            MapThemeMode.DARK to stringResource(R.string.map_theme_dark),
        )
        val currentThemeLabel = themeOptions.firstOrNull { it.first == mapThemeMode }?.second ?: ""

        ExposedDropdownMenuBox(
            expanded = themeExpanded,
            onExpandedChange = { themeExpanded = it },
        ) {
            OutlinedTextField(
                value = currentThemeLabel,
                onValueChange = {},
                readOnly = true,
                trailingIcon = { ExposedDropdownMenuDefaults.TrailingIcon(expanded = themeExpanded) },
                modifier = Modifier
                    .fillMaxWidth()
                    .menuAnchor(MenuAnchorType.PrimaryNotEditable),
            )
            ExposedDropdownMenu(
                expanded = themeExpanded,
                onDismissRequest = { themeExpanded = false },
            ) {
                themeOptions.forEach { (mode, label) ->
                    DropdownMenuItem(
                        text = { Text(label) },
                        onClick = {
                            viewModel.setMapThemeMode(mode)
                            themeExpanded = false
                        },
                    )
                }
            }
        }

        HorizontalDivider(modifier = Modifier.padding(vertical = 16.dp))

        // Floating overlay over other apps (Waze/Maps). Special permission —
        // toggling on without it sends the user to the system grant screen; the
        // service's visibility gate picks up the grant on return.
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = stringResource(R.string.setting_overlay),
                    style = MaterialTheme.typography.titleMedium,
                )
                Text(
                    text = stringResource(R.string.setting_overlay_desc),
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
            Switch(
                checked = overlayEnabled,
                onCheckedChange = { enabled ->
                    viewModel.setOverlayEnabled(enabled)
                    if (enabled && !Settings.canDrawOverlays(context)) {
                        requestOverlayPermission(context)
                    }
                },
            )
        }

        HorizontalDivider(modifier = Modifier.padding(vertical = 16.dp))

        // Automatic zone updates — opt-out for the periodic background sync.
        // The "Sync zones now" button below stays available regardless.
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Text(
                text = stringResource(R.string.setting_zone_sync),
                style = MaterialTheme.typography.titleMedium,
                modifier = Modifier.weight(1f),
            )
            Switch(
                checked = zoneSyncEnabled,
                onCheckedChange = { viewModel.setZoneSyncEnabled(it) },
            )
        }
        Text(
            text = stringResource(R.string.setting_zone_sync_desc),
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )

        Spacer(modifier = Modifier.height(12.dp))

        // Sync
        Button(
            onClick = { viewModel.syncNow() },
            enabled = !isSyncing,
            modifier = Modifier.fillMaxWidth(),
        ) {
            if (isSyncing) {
                CircularProgressIndicator(
                    modifier = Modifier.size(18.dp),
                    strokeWidth = 2.dp,
                    color = LocalContentColor.current,
                )
                Spacer(modifier = Modifier.width(8.dp))
            }
            Text(stringResource(R.string.setting_sync_now))
        }

        Spacer(modifier = Modifier.height(8.dp))

        Text(
            text = stringResource(R.string.setting_zone_data_date, formatZoneVersion(zoneDataVersion)),
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Text(
            text = stringResource(R.string.setting_zone_data_count, zoneCount),
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Text(
            text = stringResource(R.string.setting_zone_data_hash, shortZoneHash(zoneDataHash)),
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            // Tagged as the QA anchor for the zone-data block: it's the last
            // row that is *always* present, so a scenario can scroll to it and
            // then assert on the conditional notice below. Same id as the iOS
            // row's accessibilityIdentifier.
            modifier = Modifier
                .semantics { testTagsAsResourceId = true }
                .testTag("settings-zone-data-hash"),
        )
        // Shown only once the server says this build's data feed is retired.
        // Deliberately below the hash: the three lines above say *what* data is
        // installed, and this one says why it has stopped changing.
        if (zoneFeedUnsupported) {
            Text(
                text = stringResource(R.string.setting_zone_data_unsupported),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.error,
                modifier = Modifier
                    .semantics { testTagsAsResourceId = true }
                    .testTag("settings-zone-data-unsupported"),
            )
        }

        HorizontalDivider(modifier = Modifier.padding(vertical = 16.dp))

        // About
        Text(
            text = stringResource(R.string.about_title),
            style = MaterialTheme.typography.titleMedium,
        )
        Spacer(modifier = Modifier.height(8.dp))
        Image(
            painter = painterResource(R.drawable.ic_logo_horizontal),
            contentDescription = "SrednaBG",
            modifier = Modifier
                .fillMaxWidth()
                .height(80.dp),
            contentScale = ContentScale.Fit,
            colorFilter = ColorFilter.tint(MaterialTheme.colorScheme.primary),
        )
        Spacer(modifier = Modifier.height(8.dp))
        Text(
            text = stringResource(R.string.about_version, BuildConfig.VERSION_NAME),
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Text(
            text = stringResource(R.string.about_license),
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )

        Spacer(modifier = Modifier.height(16.dp))

        Text(
            text = stringResource(R.string.about_attribution),
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Text(
            text = stringResource(R.string.about_zone_data),
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        }
    }
